package com.collabcase.codegen;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import java.io.ByteArrayInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.zip.ZipInputStream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import com.collabcase.ai.context.*;
import tools.jackson.databind.ObjectMapper;

class CodeGenerationTests {
    private final JavaNames names=new JavaNames();
    private final GenerationModelBuilder builder=new GenerationModelBuilder(names,new JavaTypeMapper());
    private final GenerationValidator validator=new GenerationValidator();
    private final SpringBootProjectGenerator generator=new SpringBootProjectGenerator(new ObjectMapper(),"4.1.1",new RelationshipCodeMapper());

    @Test void simpleClassWithoutIdGetsTechnicalUuidAndWarning(){var model=builder.build(context("Demo",List.of(clazz("a","Cliente",attribute("nombre","String"))),List.of()));assertThat(validator.validate(model).valid()).isTrue();assertThat(model.entities().getFirst().syntheticId()).isTrue();assertThat(model.warnings()).anyMatch(x->x.contains("UUID tecnico"));}
    @Test void explicitNumericAndUuidIdsAreGeneratedAndExcludedFromRequests(){var model=builder.build(context("Ids",List.of(clazz("a","Cliente",attribute("id","Long"),attribute("nombre","String")),clazz("b","Libro",attribute("id","Integer"),attribute("titulo","String")),clazz("c","Reserva",attribute("id","UUID"),attribute("estado","String"))),List.of()));var files=generator.generate(model);String root="ids/backend/src/main/java/"+model.packageName().replace('.','/')+"/";assertThat(new String(files.get(root+"entity/Cliente.java"))).contains("GenerationType.IDENTITY");assertThat(new String(files.get(root+"entity/Libro.java"))).contains("GenerationType.IDENTITY");assertThat(new String(files.get(root+"entity/Reserva.java"))).contains("GenerationType.UUID");assertThat(new String(files.get(root+"dto/ClienteRequest.java"))).doesNotContain("Long id");assertThat(new String(files.get(root+"service/ClienteService.java"))).doesNotContain("setId(request.id())");}
    @Test void incompatibleExplicitIdRemainsManualWithWarning(){var model=builder.build(context("Manual",List.of(clazz("a","Documento",attribute("id","String"))),List.of()));assertThat(model.entities().getFirst().id().generated()).isFalse();assertThat(validator.validate(model).warnings()).anyMatch(x->x.contains("deberá asignarse manualmente"));}
    @Test void mapsRequiredJavaTypes(){var types=new JavaTypeMapper();for(String type:List.of("String","Text","Integer","int","Long","long","Boolean","bool","Double","Float","Decimal","BigDecimal","Date","LocalDate","DateTime","LocalDateTime","UUID"))assertThat(types.map(type,java.util.Set.of()).warning()).as(type).isNull();assertThat(types.map("Money",java.util.Set.of()).javaType()).isEqualTo("String");}
    @Test void mapsJpaCardinalities(){var mapper=new RelationshipCodeMapper();assertThat(mapper.fromSource("1","1").annotation()).isEqualTo("OneToOne");assertThat(mapper.fromSource("1","0..*").annotation()).isEqualTo("OneToMany");assertThat(mapper.fromSource("0..*","1").annotation()).isEqualTo("ManyToOne");assertThat(mapper.fromSource("*","*").annotation()).isEqualTo("ManyToMany");}
    @Test void normalizesAccentedNames(){var model=builder.build(context("Sistema de Ventas Ágil",List.of(clazz("a","Órden de compra",attribute("id","Long"))),List.of()));assertThat(model.artifactId()).isEqualTo("sistema-de-ventas-agil");assertThat(model.packageName()).isEqualTo("com.collabcase.generated.sistemadeventasagil");assertThat(model.entities().getFirst().javaName()).isEqualTo("OrdenDeCompra");}
    @Test void rejectsNormalizedDuplicateClasses(){var model=builder.build(context("Demo",List.of(clazz("a","Cliente",attribute("id","Long")),clazz("b","Clíente",attribute("id","Long"))),List.of()));assertThat(validator.validate(model).valid()).isFalse();}
    @Test void rejectsDuplicateAttributes(){var model=builder.build(context("Demo",List.of(new AiClassContext("a","Cliente",List.of(attribute("Nombre","String"),attribute("Nómbre","String")),List.of())),List.of()));assertThat(validator.validate(model).errors()).anyMatch(x->x.contains("Atributo repetido"));}
    @Test void preservesAllRelationshipKindsAndDescriptor() throws Exception {var model=builder.build(context("Relations",List.of(clazz("a","A",attribute("id","Long")),clazz("b","B",attribute("id","Long"))),List.of("ClassBidirectional","ClassUnidirectional","ClassAggregation","ClassComposition","ClassInheritance","ClassDependency","ClassRealization").stream().map(t->relationship(t,"1","0..*")).toList()));assertThat(validator.validate(model).valid()).isTrue();String definition=new String(generator.generate(model).get("relations/backend/app-definition.json"));assertThat(definition).contains("\"schemaVersion\" : 1","ClassDependency","ClassComposition");}
    @Test void generatedMobileInfrastructureUsesRealEntities(){var model=builder.build(context("Mobile",List.of(clazz("a","Cliente",attribute("id","Long"),attribute("nombre","String"))),List.of()));var files=generator.generate(model);String root="mobile/backend/src/main/java/"+model.packageName().replace('.','/')+"/";assertThat(new String(files.get(root+"entity/Cliente.java"))).contains("UUID syncId","@Version");assertThat(new String(files.get(root+"repository/ClienteRepository.java"))).contains("findBySyncId");assertThat(new String(files.get(root+"mobile/ClienteMobileSyncAdapter.java"))).contains("ClienteRepository","saveAndFlush").doesNotContain("RuntimeRecord");assertThat(new String(files.get(root+"mobile/MobileController.java"))).contains("/api/mobile","X-Mobile-Token");assertThat(new String(files.get("mobile/backend/src/main/resources/application.properties"))).contains("MOBILE_API_TOKEN");}
    @Test void unknownRelationshipIsBlocking(){var model=builder.build(context("Demo",List.of(clazz("a","A",attribute("id","Long")),clazz("b","B",attribute("id","Long"))),List.of(relationship("Unknown",null,null))));assertThat(validator.validate(model).valid()).isFalse();}
    @Test void generatedArtifactContainsBackendAndStaticMobileTemplate(){var model=builder.build(context("Biblioteca",List.of(clazz("a","Cliente",attribute("id","Long"))),List.of()));var files=generator.generate(model);assertThat(files).containsKeys("biblioteca/README.md","biblioteca/backend/pom.xml","biblioteca/mobile/pubspec.yaml","biblioteca/mobile/lib/main.dart","biblioteca/mobile/android/app/build.gradle.kts","biblioteca/mobile/android/gradle/wrapper/gradle-wrapper.jar","biblioteca/mobile/android/gradle/wrapper/gradle-wrapper.properties","biblioteca/mobile/assets/asr/README_ASR.md","biblioteca/mobile/lib/voice/offline_speech_service.dart","biblioteca/mobile/lib/ai/local_ai_service.dart");assertThat(files.keySet()).noneMatch(path->SpringBootProjectGenerator.isBuildArtifact(path));String mobileConfig=new String(files.get("biblioteca/mobile/lib/config/app_config.dart"));assertThat(mobileConfig).contains("BACKEND_URL","MOBILE_API_TOKEN");}
    @Test void mobileTemplateFilterOnlyDropsBuildArtifacts(){
        for(String path:List.of("build/app.apk","android/build/reports/problems/problems-report.html","android/.gradle/cache.bin","nested/.dart_tool/package_config.json","plugin/build/output.bin","lib/.idea/workspace.xml","coverage/lcov.info","models/qwen.gguf","android/app/build/outputs/app.aab",".flutter-plugins-dependencies","android/local.properties"))assertThat(SpringBootProjectGenerator.isBuildArtifact(path)).as(path).isTrue();
        for(String path:List.of("android/gradle/wrapper/gradle-wrapper.jar","android/gradle/wrapper/gradle-wrapper.properties","assets/asr/README_ASR.md","lib/main.dart"))assertThat(SpringBootProjectGenerator.isBuildArtifact(path)).as(path).isFalse();
    }
    @Test void generatedBibliotecaHasOnlyMobileSources(@TempDir Path temp) throws Exception {
        var model=builder.build(context("Biblioteca",List.of(clazz("a","Cliente",attribute("id","Long"))),List.of()));
        unzip(new ZipService().zip(generator.generate(model)),temp);
        Path mobile=temp.resolve("biblioteca/mobile");
        for(String required:List.of("pubspec.yaml","lib/main.dart","android/app/build.gradle.kts","android/gradle/wrapper/gradle-wrapper.jar","android/gradle/wrapper/gradle-wrapper.properties","assets/asr/README_ASR.md","assets/asr/encoder.int8.onnx","assets/asr/decoder.int8.onnx","assets/asr/tokens.txt","lib/voice/offline_speech_service.dart","lib/ai/local_ai_service.dart"))assertThat(Files.exists(mobile.resolve(required))).as(required).isTrue();
        for(String forbidden:List.of("build",".dart_tool","android/build","android/.gradle","third_party"))assertThat(Files.exists(mobile.resolve(forbidden))).as(forbidden).isFalse();
    }
    @Test void generatedMobileUsesPublishedOfflineAiAndAsr(){
        var model=builder.build(context("Biblioteca",List.of(clazz("a","Cliente",attribute("id","Long"))),List.of()));
        var files=generator.generate(model);
        String root="biblioteca/mobile/";
        assertThat(new String(files.get(root+"pubspec.yaml"))).contains("lib_llama_cpp:","sherpa_onnx:","flutter_tts:").doesNotContain("vosk","third_party");
        assertThat(new String(files.get(root+"lib/data/remote/mobile_api_client.dart"))).contains("/api/mobile/definition","/api/mobile/changes","/api/mobile/sync").doesNotContain("/api/runtime");
        String localAi=new String(files.get(root+"lib/ai/local_ai_service.dart"));
        assertThat(localAi)
            .contains("LlamaGenerateCommand(","mode=plain_text","tools=false","grammarEnabled=false","jsonSchema=false")
            .doesNotContain("LlamaGenerateMessagesCommand","LlamaToolChoice","LlamaTool(","responseFormat:","grammar:");
    }
    @Test void generatedBidirectionalManyToManyHasDeterministicOwnerAndIds(){var model=builder.build(context("Universidad",List.of(clazz("a","Estudiante",attribute("id","Long")),clazz("b","Curso",attribute("id","Long"))),List.of(relationship("ClassBidirectional","0..*","0..*"))));var files=generator.generate(model);String root="universidad/backend/src/main/java/"+model.packageName().replace('.','/')+"/";String curso=new String(files.get(root+"entity/Curso.java"));String estudiante=new String(files.get(root+"entity/Estudiante.java"));assertThat(curso).contains("@ManyToMany","@JoinTable(name=\"curso_estudiante\"","Set<Estudiante>");assertThat(estudiante).contains("@ManyToMany(mappedBy=\"estudianteSet\")","Set<Curso>").doesNotContain("@JoinTable");assertThat(new String(files.get(root+"dto/CursoRequest.java"))).contains("Set<Long> estudianteIds");assertThat(new String(files.get("universidad/backend/app-definition.json"))).contains("\"sourceEntity\" : \"Estudiante\"","\"targetEntity\" : \"Curso\"","\"relationType\" : \"MANY_TO_MANY\"","\"multiple\" : true","cursoSyncIds");}
    @Test void generatedUnidirectionalManyToManyHasOnlySourceCollection(){var model=builder.build(context("Universidad",List.of(clazz("a","Estudiante",attribute("id","Long")),clazz("b","Curso",attribute("id","Long"))),List.of(relationship("ClassUnidirectional","*","*"))));var files=generator.generate(model);String root="universidad/backend/src/main/java/"+model.packageName().replace('.','/')+"/entity/";assertThat(new String(files.get(root+"Estudiante.java"))).contains("@ManyToMany","@JoinTable");assertThat(new String(files.get(root+"Curso.java"))).doesNotContain("@ManyToMany");}
    @Test void generatedProjectCompilesWithMaven(@TempDir Path temp) throws Exception {var cliente=new AiClassContext("cliente","Cliente",List.of(attribute("id","Long"),attribute("nombre","String"),attribute("correo","String")),List.of());var libro=new AiClassContext("libro","Libro",List.of(attribute("id","Long"),attribute("titulo","String"),attribute("autor","String"),attribute("disponible","Boolean")),List.of());var reserva=new AiClassContext("reserva","Reserva",List.of(attribute("id","UUID"),attribute("fecha","LocalDate"),attribute("estado","String")),List.of());var pago=new AiClassContext("pago","Pago",List.of(attribute("id","Long"),attribute("monto","BigDecimal")),List.of());var relationships=List.of(new AiRelationshipContext("r1","cliente","Cliente","reserva","Reserva","ClassUnidirectional","1","0..*",null),new AiRelationshipContext("r2","libro","Libro","reserva","Reserva","ClassUnidirectional","1","0..*",null),new AiRelationshipContext("r3","reserva","Reserva","pago","Pago","ClassUnidirectional","1","0..1",null),new AiRelationshipContext("r4","cliente","Cliente","libro","Libro","ClassBidirectional","0..*","0..*",null));var model=builder.build(context("Sistema Biblioteca",List.of(cliente,libro,reserva,pago),relationships));assertThat(validator.validate(model).valid()).isTrue();byte[] zip=new ZipService().zip(generator.generate(model));unzip(zip,temp);Path project=temp.resolve("sistema-biblioteca/backend");Process process=new ProcessBuilder(maven(),"-q","clean","test").directory(project.toFile()).redirectErrorStream(true).start();String output=new String(process.getInputStream().readAllBytes());assertThat(process.waitFor()).as(output).isZero();}

    private void unzip(byte[] bytes,Path target)throws Exception{try(var zip=new ZipInputStream(new ByteArrayInputStream(bytes))){for(var entry=zip.getNextEntry();entry!=null;entry=zip.getNextEntry()){Path path=target.resolve(entry.getName()).normalize();if(!path.startsWith(target))throw new IllegalArgumentException();if(entry.isDirectory())Files.createDirectories(path);else{Files.createDirectories(path.getParent());Files.write(path,zip.readAllBytes());}}}}
    private String maven(){return System.getProperty("os.name").toLowerCase().contains("win")?"mvn.cmd":"mvn";}
    private AiDiagramContext context(String title,List<AiClassContext> classes,List<AiRelationshipContext> relationships){return new AiDiagramContext("diagram-id",title,"ClassDiagram",classes,relationships);}
    private AiClassContext clazz(String id,String name,AiAttributeContext...attributes){return new AiClassContext(id,name,List.of(attributes),List.of());}
    private AiAttributeContext attribute(String name,String type){return new AiAttributeContext(name,name,type,"+ "+name+": "+type);}
    private AiRelationshipContext relationship(String type,String source,String target){return new AiRelationshipContext(type,"a","A","b","B",type,source,target,null);}
}
